'use client';

import { useEffect, useId, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import './agent-activity-wall.css';

export interface AgentActivityItem {
  id: string;
  name: string;
  role: string;
  initial?: string;
  mention?: string;
  request: string;
  response: string;
  color: string;
  mentionColor?: string;
  avatar?: ReactNode;
  tools?: { id:string; label:string; logo:ReactNode }[];
}
export interface AgentActivityWallProps {
  columns: AgentActivityItem[][];
  title?: ReactNode;
  durations?: number[];
  paused?: boolean;
  showControls?: boolean;
  className?: string;
}

/** Opposing vertical streams of requests and completed work, with a static accessible copy. */
export function AgentActivityWall({ columns, title='An agent that does everything.', durations=[64,76,70], paused=false, showControls=true, className='' }: AgentActivityWallProps) {
  const uid = useId();
  const root = useRef<HTMLElement>(null);
  const [held,setHeld] = useState(false);
  const [copies,setCopies] = useState<number[]>([]);
  const [environment,setEnvironment] = useState({ visible:false,hidden:false,reduced:false });
  useEffect(()=>{
    const element=root.current;
    if (!element) return;
    const media=matchMedia('(prefers-reduced-motion: reduce)');
    let visible=typeof IntersectionObserver==='undefined';
    const sync=()=>setEnvironment({ visible,hidden:document.hidden,reduced:media.matches });
    const observer=typeof IntersectionObserver==='undefined'?null:new IntersectionObserver(([entry])=>{ visible=entry.isIntersecting;sync(); });
    observer?.observe(element);
    media.addEventListener('change',sync);
    document.addEventListener('visibilitychange',sync);
    sync();
    return ()=>{observer?.disconnect();media.removeEventListener('change',sync);document.removeEventListener('visibilitychange',sync);};
  },[]);
  useEffect(()=>{
    const element=root.current;
    if (!element) return;
    const measure=()=>{
      const viewport=element.querySelector<HTMLElement>('.ac-agent-wall__window');
      const next=Array.from(element.querySelectorAll<HTMLElement>('.ac-agent-wall__column')).map(column=>{
        const height=column.querySelector<HTMLElement>('.ac-agent-wall__group')?.getBoundingClientRect().height??0;
        return height>0?Math.max(2,Math.min(32,Math.ceil((viewport?.clientHeight??600)/height)+1)):2;
      });
      setCopies(previous=>previous.length===next.length&&previous.every((count,index)=>count===next[index])?previous:next);
    };
    const observer=typeof ResizeObserver==='undefined'?null:new ResizeObserver(measure);
    observer?.observe(element);
    element.querySelectorAll('.ac-agent-wall__group').forEach(group=>observer?.observe(group));
    window.addEventListener('resize',measure);
    measure();
    return ()=>{observer?.disconnect();window.removeEventListener('resize',measure);};
  },[columns]);
  const running=environment.visible&&!environment.hidden&&!environment.reduced&&!paused&&!held;
  function card(item:AgentActivityItem,copy:number) {
    return <figure className="ac-agent-wall__card" key={item.id} style={{'--ac-agent-color':item.color,'--ac-agent-mention':item.mentionColor??'#342c47'} as CSSProperties}>
      <figcaption><span className="ac-agent-wall__initial">{item.initial??item.name.slice(0,1)}</span><span className="ac-agent-wall__name">{item.name}</span><span className="ac-agent-wall__role">{item.role}</span></figcaption>
      <blockquote><span className="ac-agent-wall__mention">{item.mention??'@Agent'}</span>{' '}{item.request}</blockquote>
      <div className="ac-agent-wall__result"><span className="ac-agent-wall__avatar" aria-hidden="true">{item.avatar??<svg viewBox="0 0 24 24" fill="none"><path d="m6 12 4 4 8-9" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>}</span><p>{item.response}</p>{item.tools&&item.tools.length>0&&<span className="ac-agent-wall__tools">{item.tools.map(tool=><span key={tool.id} className="ac-agent-wall__tool" title={tool.label} role={copy===0?'img':undefined} aria-label={copy===0?tool.label:undefined}>{tool.logo}</span>)}</span>}</div>
    </figure>;
  }
  return <section ref={root} className={`ac-agent-wall ${className}`.trim()} aria-labelledby={`${uid}-title`} data-running={running}>
    <div className="ac-agent-wall__header"><h2 id={`${uid}-title`}>{title}</h2></div>
    <div className="ac-agent-wall__window" role="region" aria-label="Agent activity examples" tabIndex={environment.reduced?0:undefined}>
      {columns.filter(column=>column.length>0).slice(0,3).map((column,index)=><div className="ac-agent-wall__column" key={index}>
        <div className="ac-agent-wall__track" data-reverse={index%2===1} style={{'--ac-agent-copies':copies[index]??2,'--ac-agent-duration':`${Number.isFinite(durations[index])?Math.max(20,Math.min(300,durations[index])):64}s`} as CSSProperties}>
          {Array.from({length:copies[index]??2},(_,copy)=>copy).map(copy=><div className="ac-agent-wall__group" key={copy} aria-hidden={copy>0?true:undefined}>{column.map(item=>card(item,copy))}</div>)}
        </div>
      </div>)}
    </div>
    {showControls&&<div className="ac-agent-wall__controls"><button type="button" onClick={()=>setHeld(value=>!value)} disabled={paused||environment.reduced} aria-pressed={held||paused}>{environment.reduced?'Motion reduced':held||paused?'Play motion':'Pause motion'}</button></div>}
  </section>;
}

.ac-agent-wall { --ac-agent-theme-surface:#fcfbff; --ac-agent-theme-ink:#181630; --ac-agent-theme-muted:#68647f; --ac-agent-theme-faint:#a09bb8; --ac-agent-theme-line:#e8e6ed; --ac-agent-theme-avatar:#f5f3fa; container-type:inline-size; overflow:hidden; padding:64px 0 52px; background:var(--ac-agent-surface,var(--ac-agent-theme-surface)); color:var(--ac-agent-ink,var(--ac-agent-theme-ink)); font-family:var(--ac-agent-font,Geist,Arial,sans-serif); }
.ac-agent-wall *, .ac-agent-wall *::before, .ac-agent-wall *::after { box-sizing:border-box; }
.ac-agent-wall__header { width:100%; max-width:1200px; margin-inline:auto; padding-inline:32px; }
.ac-agent-wall__header h2 { margin:0; font-size:64px; line-height:1; font-weight:500; letter-spacing:-.02em; text-wrap:balance; }
.ac-agent-wall__window { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; width:100%; max-width:1200px; height:600px; margin:64px auto 0; padding-inline:32px; overflow:hidden; mask-image:linear-gradient(transparent,#000 12%,#000 88%,transparent); }
.ac-agent-wall__window:focus-visible { outline:2px solid currentColor; outline-offset:-3px; }
.ac-agent-wall__column { min-width:0; }
.ac-agent-wall__track { display:flex; flex-direction:column; animation:ac-agent-wall-up var(--ac-agent-duration,64s) linear infinite; }
.ac-agent-wall__track[data-reverse='true'] { animation-direction:reverse; }
.ac-agent-wall__group { display:flex; flex-direction:column; gap:16px; padding-bottom:16px; }
.ac-agent-wall__card { min-width:0; margin:0; padding:20px; border:1px solid var(--ac-agent-line,var(--ac-agent-theme-line)); border-radius:20px; background:var(--ac-agent-surface,var(--ac-agent-theme-surface)); }
.ac-agent-wall__card figcaption { display:flex; align-items:center; gap:10px; min-width:0; }
.ac-agent-wall__initial { display:grid; place-items:center; flex-shrink:0; width:28px; height:28px; border-radius:50%; background:var(--ac-agent-avatar,var(--ac-agent-theme-avatar)); box-shadow:inset 0 0 0 1px var(--ac-agent-line,var(--ac-agent-theme-line)); font-size:12px; font-weight:500; }
.ac-agent-wall__name { font-size:13.5px; line-height:1.4; font-weight:500; }
.ac-agent-wall__role { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--ac-agent-faint,var(--ac-agent-theme-faint)); font-size:13px; line-height:1.4; }
.ac-agent-wall__card blockquote { margin:14px 0 0; font-size:16.5px; line-height:1.45; letter-spacing:-.01em; text-wrap:pretty; }
.ac-agent-wall__mention { padding:3px 5px; border-radius:4px; background:color-mix(in srgb,var(--ac-agent-color) 30%,transparent); color:var(--ac-agent-mention); font-weight:500; box-decoration-break:clone; -webkit-box-decoration-break:clone; }
.ac-agent-wall__result { display:flex; align-items:center; gap:10px; margin-top:16px; padding-top:16px; border-top:1px solid var(--ac-agent-line,var(--ac-agent-theme-line)); }
.ac-agent-wall__avatar { display:grid; place-items:center; flex-shrink:0; width:26px; height:26px; border-radius:50%; background:#fff; box-shadow:inset 0 0 0 1px #00000012; color:var(--ac-agent-color); }
.ac-agent-wall__avatar > :is(svg,img) { display:block; width:24px; height:24px; object-fit:contain; }
.ac-agent-wall__result p { flex:1; min-width:0; margin:0; color:var(--ac-agent-muted,var(--ac-agent-theme-muted)); font-size:13.5px; line-height:1.375; text-wrap:pretty; }
.ac-agent-wall__tools { display:flex; flex-shrink:0; padding-left:4px; }
.ac-agent-wall__tool { display:grid; place-items:center; flex-shrink:0; width:24px; height:24px; margin-left:-6px; border:1px solid #e8e6ed; outline:2px solid var(--ac-agent-surface,var(--ac-agent-theme-surface)); border-radius:7px; background:#fff; }
.ac-agent-wall__tool > :is(svg,img) { display:block; width:12px; height:12px; object-fit:contain; }
.ac-agent-wall__controls { display:flex; justify-content:flex-end; width:100%; max-width:1200px; margin:14px auto 0; padding-inline:32px; }
.ac-agent-wall__controls button { min-height:36px; padding:4px 0; border:0; background:transparent; color:var(--ac-agent-muted,var(--ac-agent-theme-muted)); font:inherit; font-size:11px; line-height:1.4; cursor:pointer; text-underline-offset:4px; }
.ac-agent-wall__controls button:hover:not(:disabled) { color:inherit; text-decoration:underline; }
.ac-agent-wall__controls button:focus-visible { outline:2px solid currentColor; outline-offset:5px; }
.ac-agent-wall__controls button:disabled { cursor:default; opacity:.65; }
.ac-agent-wall[data-running='false'] .ac-agent-wall__track { animation-play-state:paused; }
@keyframes ac-agent-wall-up { to { transform:translateY(calc(-100% / var(--ac-agent-copies,2))); } }
@container (max-width:979px) { .ac-agent-wall__header h2 { font-size:56px; } .ac-agent-wall__window { grid-template-columns:repeat(2,minmax(0,1fr)); margin-top:48px; } .ac-agent-wall__column:last-child { display:none; } }
@container (max-width:599px) { .ac-agent-wall__header,.ac-agent-wall__window,.ac-agent-wall__controls { padding-inline:20px; } .ac-agent-wall__header h2 { font-size:44px; } .ac-agent-wall__window { grid-template-columns:minmax(0,1fr); height:540px; } .ac-agent-wall__column:not(:first-child) { display:none; } }
:where([data-theme='dark'],.dark) .ac-agent-wall { --ac-agent-theme-surface:#1b1a22; --ac-agent-theme-ink:#f4f2fb; --ac-agent-theme-muted:#b6b1ca; --ac-agent-theme-faint:#9d96b1; --ac-agent-theme-line:#383541; --ac-agent-theme-avatar:#272331; color-scheme:dark; }
:where([data-theme='dark'],.dark) .ac-agent-wall__mention { color:var(--ac-agent-color); }
@media (prefers-reduced-motion:reduce) { .ac-agent-wall__track { animation:none; } .ac-agent-wall__group[aria-hidden='true'] { display:none; } .ac-agent-wall__window { height:600px; overflow:auto; mask-image:none; overscroll-behavior:contain; } }
